Complejidad ciclomática y cobertura de c.ejemplo:
# V(G) = 4 (1 base + if + and + for) -> mínimo 4 tests para cobertura total de ramas
def calcular_total(items, aplicar_minimo):
    if not items and aplicar_minimo:  # +2 decisiones (if, and)
        return 10.0
    total = 0.0
    for item in items:                # +1 decisión (for)
        total += item.precio
    return total
